import{_ as s,o as a,c as e,ao as t}from"./chunks/framework.D54b0YE9.js";const c=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),n={name:"troubleshooting.md"};function l(h,i,o,r,p,d){return a(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="Troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#Troubleshooting" aria-label="Permalink to &quot;Troubleshooting {#Troubleshooting}&quot;">​</a></h1><p>What to do when a fit fails, stalls, or returns something implausible. Each entry names the symptom first, so you can scan for yours.</p><h2 id="get_convergedres-is-false" tabindex="-1"><code>get_converged(res)</code> is <code>false</code> <a class="header-anchor" href="#get_convergedres-is-false" aria-label="Permalink to &quot;`get_converged(res)` is `false` {#get_convergedres-is-false}&quot;">​</a></h2><p><code>get_converged</code> reports what the optimizer said about its own stopping criterion. It is not a statement about the quality of the fit: a fit can stop at <code>maxiters</code> with perfectly usable estimates, and a fit can report success at a poor local optimum. Treat it as one signal among several, never as a gate.</p><p>Check, in this order: 2. <code>get_objective(res)</code> - is it finite and better than at the starting values?</p><ol start="3"><li><p><code>NoLimits.summarize(res)</code> - do the estimates sit on a bound, or at an implausible order of magnitude?</p></li><li><p><code>plot_fits(res)</code> - do the predictions track the data? A picture settles most of these questions faster than any number.</p></li></ol><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">get_objective</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(res)              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># finite, and better than at the starting values?</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">summarize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(res)         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># estimates on a bound, or implausible in magnitude?</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">plot_fits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(res)                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># do the predictions track the data?</span></span></code></pre></div><p>If the optimizer simply ran out of budget, raise it:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dm, NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Laplace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; optim_kwargs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (; maxiters </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span></code></pre></div><h2 id="The-fit-stops-at-a-poor-optimum" tabindex="-1">The fit stops at a poor optimum <a class="header-anchor" href="#The-fit-stops-at-a-poor-optimum" aria-label="Permalink to &quot;The fit stops at a poor optimum {#The-fit-stops-at-a-poor-optimum}&quot;">​</a></h2><p>Nonlinear mixed-effects objectives are routinely multimodal. Two remedies, cheapest first:</p><ul><li><p><strong>Warm-start from a pooled fit</strong> - a fast naive-pooled fit hands its estimates to the real estimator. See <a href="./estimation/pooled">Pooled / PooledMap</a>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dm, NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Laplace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); pooled_init </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div></li><li><p><strong>Search from several starting points</strong> - see <a href="./estimation/multistart">Multistart</a>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ms </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Multistart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; dists </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (; A0 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> LogNormal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)), n_draws_requested </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, n_draws_used </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ms, dm, NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Laplace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div></li></ul><p>Poor scaling is the other common cause. Parameters that differ by many orders of magnitude make the objective badly conditioned; declare them with <code>scale = :log</code> in <code>@fixedEffects</code> so the optimizer works on a comparable scale.</p><h2 id="The-objective-is-NaN-or-Inf" tabindex="-1">The objective is <code>NaN</code> or <code>-Inf</code> <a class="header-anchor" href="#The-objective-is-NaN-or-Inf" aria-label="Permalink to &quot;The objective is `NaN` or `-Inf` {#The-objective-is-NaN-or-Inf}&quot;">​</a></h2><p>Usually the model was evaluated somewhere it is not defined: a negative variance, a <code>log</code> of a non-positive prediction, or an ODE solve that failed. Fixes:</p><ul><li><p>Constrain the parameter with <code>scale = :log</code> (or model bounds) instead of letting the optimizer step into the invalid region.</p></li><li><p>Guard the formula itself, for example with a softplus on a quantity that must stay positive.</p></li><li><p>The optimization-based methods take <code>nan_recovery = :backtrack</code> (the default), which retries a shorter step instead of aborting:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dm, NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Laplace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; nan_recovery </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :backtrack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div></li></ul><h2 id="Laplace-or-FOCEI-reports-a-non-positive-definite-Hessian" tabindex="-1">Laplace or FOCEI reports a non-positive-definite Hessian <a class="header-anchor" href="#Laplace-or-FOCEI-reports-a-non-positive-definite-Hessian" aria-label="Permalink to &quot;Laplace or FOCEI reports a non-positive-definite Hessian {#Laplace-or-FOCEI-reports-a-non-positive-definite-Hessian}&quot;">​</a></h2><p>The inner empirical-Bayes problem needs a positive-definite curvature matrix. When it is not, the method adds a small jitter to the diagonal and retries. The relevant <code>Laplace</code> / <code>FOCEI</code> options are <code>jitter</code>, <code>max_tries</code>, <code>jitter_growth</code>, <code>adaptive_jitter</code>, and <code>jitter_scale</code> (see <a href="./estimation/laplace">Laplace</a> for the shipped defaults):</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dm, NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Laplace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; jitter </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0e-5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, max_tries </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, jitter_growth </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>Persistent non-positive-definiteness is usually a modeling signal rather than a numerical one: the model is close to unidentified in the random effects at those parameter values. Reducing the number of random effects, or fixing one of them with <code>constants_re</code>, is often the real fix.</p><h2 id="The-ODE-solver-fails-or-the-fit-is-very-slow" tabindex="-1">The ODE solver fails or the fit is very slow <a class="header-anchor" href="#The-ODE-solver-fails-or-the-fit-is-very-slow" aria-label="Permalink to &quot;The ODE solver fails or the fit is very slow {#The-ODE-solver-fails-or-the-fit-is-very-slow}&quot;">​</a></h2><ul><li><p><strong>Stiffness.</strong> The default solver is a good general choice, but a stiff system needs a stiff solver, as in the <a href="./tutorials/mixed-effects-nn-saem">Neural Differential Equations</a> tutorial:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> set_solver_config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model; alg </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> AutoTsit5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Rosenbrock23</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()), abstol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0e-6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, reltol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0e-6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div></li><li><p><strong>Tolerances.</strong> Tight <code>abstol</code>/<code>reltol</code> on an ODE model dominates the runtime. Loosen them through <code>set_solver_config</code> while exploring, then tighten for the final fit.</p></li><li><p><strong>Parallelism.</strong> Evaluate individuals in parallel, and start Julia with <code>-t auto</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> fit_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dm, NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Laplace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); serialization </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SciMLBase</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">EnsembleThreads</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())</span></span></code></pre></div></li><li><p><strong>Method cost.</strong> <code>MCEM</code> is the most expensive of the mixed-effects methods; <code>SAEM</code> reaches a comparable answer for far less work on most models. See <a href="/NoLimits.jl/dev/estimation/index#Choosing-a-Method">Choosing a method</a>.</p></li></ul><h2 id="An-error-names-a-package-I-have-not-installed" tabindex="-1">An error names a package I have not installed <a class="header-anchor" href="#An-error-names-a-package-I-have-not-installed" aria-label="Permalink to &quot;An error names a package I have not installed {#An-error-names-a-package-I-have-not-installed}&quot;">​</a></h2><p>Plotting, Turing-based estimation, JLD2 serialization, profile-likelihood UQ, and several other features live in package extensions. Calling one without its package raises an error that names exactly what to install. Add it once with <code>Pkg.add</code>, then <code>using</code> it. The full list is in <a href="/NoLimits.jl/dev/installation#Optional-Dependencies">Optional Dependencies</a>.</p><h2 id="Between-subject-variance-collapses-towards-zero" tabindex="-1">Between-subject variance collapses towards zero <a class="header-anchor" href="#Between-subject-variance-collapses-towards-zero" aria-label="Permalink to &quot;Between-subject variance collapses towards zero {#Between-subject-variance-collapses-towards-zero}&quot;">​</a></h2><p>An <code>omega</code> estimate at the lower edge of its range means the data do not support the random effect at that level: too few individuals, too few observations per individual, or a random effect that is not identifiable given the structural model. Refit without that random effect and compare objectives before concluding that the variance is genuinely small.</p><h2 id="The-same-fit-gives-slightly-different-numbers" tabindex="-1">The same fit gives slightly different numbers <a class="header-anchor" href="#The-same-fit-gives-slightly-different-numbers" aria-label="Permalink to &quot;The same fit gives slightly different numbers {#The-same-fit-gives-slightly-different-numbers}&quot;">​</a></h2><p>Per-individual quantities are bitwise reproducible; the population objective is reproducible only up to floating-point summation order, and the fitted parameters only up to the conditioning of the problem. <a href="./estimation/reproducibility">Reproducibility and Individual Order</a> gives the measured magnitudes and the tolerances to use when comparing fits.</p><h2 id="Still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#Still-stuck" aria-label="Permalink to &quot;Still stuck {#Still-stuck}&quot;">​</a></h2><p>Open an issue at <a href="https://github.com/manuhuth/NoLimits.jl/issues" target="_blank" rel="noreferrer">github.com/manuhuth/NoLimits.jl</a> with the model definition, a minimal data frame that reproduces the problem, and the output of:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NoLimits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">summarize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dm)</span></span></code></pre></div>',31)])])}const g=s(n,[["render",l]]);export{c as __pageData,g as default};
